def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "u-": 3, "^": 4}

    def apply():
        op = operators.pop()
        if op == "u-":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                raise ValueError
            values.append(pow(a, b))
        else:
            if b == 0:
                raise ValueError
            q = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                q = -q
            values.append(q if op == "/" else a - b * q)

    i = 0
    expect_operand = True

    try:
        while i < len(expr):
            c = expr[i]

            if c == " ":
                i += 1
            elif "0" <= c <= "9":
                number = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    number = number * 10 + ord(expr[i]) - ord("0")
                    i += 1
                values.append(number)
                expect_operand = False
            elif c == "(":
                operators.append(c)
                i += 1
                expect_operand = True
            elif c == ")":
                while operators[-1] != "(":
                    apply()
                operators.pop()
                i += 1
                expect_operand = False
            elif c == "-" and expect_operand:
                operators.append("u-")
                i += 1
            else:
                while (
                    operators
                    and operators[-1] != "("
                    and (
                        precedence[operators[-1]] > precedence[c]
                        or (
                            precedence[operators[-1]] == precedence[c]
                            and c != "^"
                        )
                    )
                ):
                    apply()
                operators.append(c)
                i += 1
                expect_operand = True

        while operators:
            apply()
        return values[0]
    except ValueError:
        return "error"
